        const langLabel = document.createElement('span');
        langLabel.style.color = isShellCommand ? '#f59e0b' : '#38bdf8';
        langLabel.style.fontWeight = 'bold';
        langLabel.textContent = detectedPath
            ? `▶ 📄 ${detectedPath}`
