    tools: boolean;
    vision: boolean;
    embedding: boolean;
}

export function getModelCapabilities(modelName: string): ModelCapabilities {
    const l = (modelName || '').toLowerCase();
    const thinking =
        l.includes('r1') ||
        l.includes('reasoner') ||
        l.includes('qwq') ||
        l.includes('nemotron-3') ||
        l.includes('thinking');
    const tools =
        l.includes('instruct') ||
        l.includes('coder') ||
        l.includes('gpt') ||
        l.includes('claude') ||
        l.includes('gemini') ||
        l.includes('llama-3');
    const vision =
        l.includes('vision') ||
        l.includes('vl') ||
        l.includes('gpt-4o') ||
        l.includes('gemini-1.5') ||
        l.includes('gemini-2') ||
        l.includes('claude-3');
    const embedding = l.includes('embed') || l.includes('bge') || l.includes('nomic');
    return { thinking, tools, vision, embedding };
}

